        makeup: "清透柔雾的淡雅秀场妆容，眉部采用低饱和灰棕色修饰，眼部以浅米棕色与柔和灰粉色眼影为主、眼尾略微加深；上睫毛根部具有细窄的深棕色眼线，睫毛纤细分明；面颊使用极淡的柔粉色腮红，鼻梁与颧骨具有轻微柔光高光；唇部采用低饱和珊瑚豆沙色，呈柔和半哑光质感，唇峰与唇中央保留细腻色彩层次。",
