        bangs: "无独立齐刘海或碎刘海；前额采用接近中分的整洁梳发方式，额头大部分露出，左右前侧发束从中央发缝向两侧顺滑延伸、沿太阳穴方向收拢至耳后，发际线自然柔和，少量细碎发丝贴近耳侧。",
