        sleeve: "完全无袖设计，双肩及双臂裸露；左右各有一条细窄浅香槟白色肩带，自胸前领缘向肩部上方延伸，宽度较细且位置基本对称，贴合肩部曲线；没有独立袖筒、袖口或额外肩部覆盖结构。",
