        poseLegs: "双腿呈前后交替的时装秀步态：人物右腿位于画面左侧，向前伸出并接近伸直，右脚落于身体中心线附近，尖头高跟鞋鞋尖朝向前方、脚掌接近完全着地；人物左腿位于画面右侧，膝部轻微弯曲，左脚从后方跟进、脚跟略微抬起，脚尖自然下指；双腿在膝部附近形成轻微交错，膝踝方向保持协调，随着步伐推进左右腿交替承担身体重量，形成流畅连续的猫步行走动作。",
