        poseTorso: "头部向人物左后方旋转并略微低头，脸部以三分之四侧面角度回望镜头；肩部与胸廓相对骨盆明显扭转，靠近镜头一侧肩膀向前下方延伸，背部呈柔和弯曲，腰部略微前倾，颈部与肩背连接自然。",
