        face: "脸部呈小巧的鹅蛋形与柔和心形相结合的轮廓，额头较宽且圆润，颞部向颧骨区域平缓过渡，双颊具有轻微饱满感，面中长度适中偏短；颧骨位置柔和、未形成明显外凸棱角，下颌线从耳下向中央逐渐收窄，下巴小巧、略尖而末端圆润；保留圆润双颊与收束下巴的对比，使脸部骨相精致且具有辨识度。",
