        body: "整体为修长、纤细而具有柔和曲线的成年女性体型，头部相对身体较小，颈部细长，双肩较窄且自然下沉，锁骨线条清晰；上半身长度适中，胸廓与腰腹衔接平滑，腰部较细，骨盆宽度与肩部形成柔和协调的比例；双臂纤长，手腕与手指细致；双腿较长，大腿具有自然圆润度，膝部收束平缓，小腿逐渐向纤细脚踝过渡；保持原有修长腿部、窄肩与细腰的整体体型类别，适度协调关节连接，不额外拉长双腿或缩小头部。",
