        brow: "浅灰棕色细柔眉形，颜色较淡；眉头位于内眼角上方，眉身沿眉骨形成平缓的自然弧度，眉峰不明显，眉尾细致地向外延伸；眉眼距离适中，部分眉毛被额前浅色发束遮挡，整体呈柔和自然的平眉与微弯眉结合形态。",
