        makeup: "精致清透的粉蓝系甜美妆容，眼部以浅米粉色和柔和冷粉色眼影打底、眼尾轻微加深，细致深棕色眼线贴合上睫毛根部，睫毛纤长、卷翘且排列分明；下眼睑带浅粉色晕染与细微珠光提亮，卧蚕柔和；面颊以浅蜜桃粉色腮红营造自然红润感，鼻尖轻微泛粉，唇部为清透粉玫瑰色水润唇妆，整体色彩柔和，不使用浓重修容。",
        hair: "主体为银白色与浅奶油金色交融的中短蓬松卷发，发根呈柔和暖白色，发丝表面具有珍珠银色高光，局部内层发束带浅冰蓝渐变；头顶发量充足，发丝从偏侧分缝向两侧自然展开，形成饱满圆润的顶部轮廓；两侧头发沿脸颊向外蓬松弯曲，在耳下至肩部附近形成多组粗大的立体卷束，卷发末端向内或向外翻卷形成明显的螺旋弧度；画面左侧靠近颈部的卷束向内收拢，画面右侧卷发向外展开并向颈侧回卷，局部浅蓝发束位于白色主体下层；后侧头发整体保持中短长度，不延伸为长发；头顶另有两束细长的浅白色装饰性发束向上弯曲，形成一大一小、相互交叠的心形轮廓，发束根部连接于头顶后方，弧线纤细轻盈，与蓬松短卷发主体明确分离。",
        bangs: "采用轻盈的偏侧分缝结构，额前发束从头顶向两侧自然分流，中央露出部分额头；画面左侧刘海较厚，呈柔和弧线向眉眼外侧延伸，部分细碎发丝垂至眉毛附近，画面右侧刘海向外梳开、与侧面蓬松卷发衔接；发束具有明显分区和层次，发尾细薄，整体保持轻盈而非厚重齐刘海的造型。",
        accessory: "头部画面左侧偏后上方佩戴一件精致的金色宫廷式冠状发饰，主体由多根纤细金色金属枝杆构成，枝杆从较窄的基部向上及两侧分叉，形成不规则放射状的镂空冠形结构；冠饰上分布数颗大小不同的深蓝椭圆形与水滴形宝石，部分宝石纵向排列，周围点缀细小金色珠粒与叶片状装饰，顶部可见细长尖端；冠饰整体较轻薄，主要集中在头部一侧，不形成覆盖整个头顶的厚重王冠；冠饰下方及耳侧可见少量深色垂坠状装饰，与浅色卷发局部交叠；耳部大部分被卷发遮挡，未见可明确辨认的独立耳环结构。",
        neckjewelry: "颈部佩戴黑色与白色相结合的精致宫廷风颈圈，主体为贴合颈部的黑色窄带，前侧叠加白色蕾丝花边与黑色卷草状镂空装饰，形成小巧的扇形领饰；颈圈中央下方悬挂一颗纵向水滴形蓝宝石吊坠，宝石呈明亮湖蓝色、外缘具有金色包镶结构，底端连接细小金色及浅色坠饰，垂落至锁骨下方；画面左侧手腕佩戴纤细的金色圆环手镯，表面光滑并带轻微金属反射；双手未见清晰戒指，手部主要保持自然裸露状态。",
        top: "白色宫廷风收腰胸衣式连衣裙上身，与下方蓬松短裙连接为一体；胸衣主体采用柔和象牙白面料，胸前由左右两片立体弧形裁片构成，沿胸部形成自然包覆，中央具有明显的纵向拼接与收束结构；胸衣上缘呈浅心形弧线，中央嵌有黑色倒三角形布片，形成鲜明的黑白对比；衣身从胸下向腰部逐渐收窄，侧面具有贴合躯干的裁剪线，腰部由蓝色腰带横向收束；胸衣下缘与裙身连续连接，局部可见细小金色装饰扣件和精致垂坠饰链；深宝蓝肩部及袖部结构位于白色胸衣外侧，形成明显的深色外框，整体上身轮廓紧凑而立体。",
        bottom: "与白色胸衣连接的多层蓬松短裙，腰线位于自然腰部附近，裙长至大腿上段，整体呈横向展开的钟形与柔和伞形结合轮廓；裙身主体由数片白色不规则弧形裁片构成，外层裙片从腰部向两侧展开，边缘形成宽大的波浪状折线；前侧中央覆盖一片略尖的白色装饰裙片，表面具有浅色暗纹，末端向下形成柔和尖角；外层裙片下方可见多层细密白色薄纱与荷叶边，裙摆边缘形成连续的轻薄波浪褶皱；画面右侧裙摆向外展开较宽、露出具有淡金色纹样的中间裙层，画面左侧裙片略向上翻卷、露出下方层叠薄纱；整体保持短裙主体与独立蓝色垂坠飘带的结构区分，不将腰侧长飘带改写为裙摆延长部分。",
