        sleeve: "双侧采用深宝蓝色短款宫廷泡泡袖，肩部袖山高耸而蓬松，形成明显向外扩张的立体体积；袖身由具有光泽的深蓝面料构成，表面分布较大的纵向及斜向褶皱，肩部上缘叠加数片向上翻起的深蓝尖角状荷叶边，形成分层的花瓣式外轮廓；袖筒在上臂中上段收束，袖口由窄边与细密褶皱构成，边缘形成短小的波浪荷叶边；左右袖型基本对称，但受姿势与布料褶皱影响局部蓬松方向略有差异；双侧前臂与手部完全裸露。",
        socks: "双腿穿着浅白色半透明长筒丝袜，丝袜主体紧贴腿部，颜色接近柔和奶白，具有细腻的半透明质感，腿部自然肤色隐约透出；两侧大腿上段各有一圈较宽的白色蕾丝袜口装饰，位置接近大腿中上部，蕾丝边缘由连续扇形花纹和细小镂空结构构成；袜口正面分别装饰小型蓝色蝴蝶结与金色金属件，中央镶嵌蓝色宝石，蝴蝶结下方悬挂细小金色及浅色坠饰；袜口以下的丝袜表面平整，未见明显纵向花纹，丝袜向下延伸至鞋内。",
        shoes: "白色宫廷风高跟鞋，鞋头为圆润偏尖的杏仁形，鞋面采用光滑的象牙白皮革质感、具有柔和光泽；鞋口较低，露出脚背上部，鞋面前端沿弧形边缘设置细窄金色装饰线，鞋头中央镶嵌一颗小型椭圆形亮蓝宝石，外侧由金色包镶与细小装饰线环绕；鞋面两侧向上延伸出细窄白色鞋带，在脚踝前方形成横向扣带，连接位置带有细小金色扣件；鞋跟较高且纤细，后跟结构向下延伸形成细跟，鞋底厚度适中；左右鞋型一致，近景鞋子因透视显得略大。",
