        poseLegs: "双腿基本伸直，形成轻微交叉站姿；画面右侧前景腿从骨盆向下延伸，膝部自然伸展，小腿略向画面中央倾斜，脚部位于前方，鞋尖朝向镜头略偏画面左侧；画面左侧腿从后方斜向画面右侧延伸，与前景腿在膝部以下形成交叠，膝关节保持轻微放松，脚部位于相对后侧，鞋尖略向画面左前方；两腿交叉幅度较小，膝部与脚踝位置自然协调，高跟鞋鞋底均与地面接触。",
